import { log } from "./logging.js";
import { ContactCard } from "@keyhive/keyhive/slim";
import { receiveContactCard } from "./keyhive/keyhive.js";
export async function syncServerFromContactCard(contactCardJson, serverPeerId, keyhive, keyhiveStorage) {
    log.debug("[AMRepoKeyhive] syncServerFromContactCard: parsing server contact card");
    const serverContactCard = ContactCard.fromJson(contactCardJson);
    const serverIndividual = await receiveContactCard(keyhive, serverContactCard, keyhiveStorage);
    if (!serverIndividual) {
        throw Error(`Invalid server contact card: ${contactCardJson}`);
    }
    const individualId = serverIndividual.id.toBytes();
    return {
        individualId,
        contactCard: serverContactCard,
        peerId: serverPeerId,
    };
}
